const posts = await Post.findAll({ include: [{ model: User, as: 'author' }] });
```

```jsx
// BAD — new object reference on every render triggers child re-render
function Parent() {
  const config = { theme: 'dark' }; // recreated every render
  return <Child config={config} />;
}

// GOOD
function Parent() {
  const config = useMemo(() => ({ theme: 'dark' }), []);
  return <Child config={config} />;
}
```

```js
// BAD — expensive computation on every call
function getReport(data) {
  return data.reduce(/* heavy aggregation */);
}

// GOOD — memoize with a fast cache
const cache = new Map();
function getReport(key, data) {
  if (cache.has(key)) return cache.get(key);
  const result = data.reduce(/* heavy aggregation */);
  cache.set(key, result);
  return result;
}
```

```jsx
// BAD — setInterval keeps running after component unmounts
useEffect(() => {
  const id = setInterval(fetchData, 5000);
}, []); // missing cleanup

// GOOD
useEffect(() => {
  const id = setInterval(fetchData, 5000);
  return () => clearInterval(id); // cleanup on unmount
}, []);
```

```jsx
// BAD — filters full list on every keystroke
function List({ items, query }) {
  const filtered = items.filter(i => i.name.includes(query)); // runs every render
  ...
}

// GOOD
function List({ items, query }) {
  const filtered = useMemo(
    () => items.filter(i => i.name.includes(query)),
    [items, query]
  );
  ...
}
